import React, { useEffect, useState, useRef } from 'react';
import { fetchReviews } from '../api/reviewApi';
import ReviewCard from '../components/ReviewCard';
import axios from '../api/axiosConfig';

function Magazine() {
  const [summary, setSummary] = useState(null);
  const [loading, setLoading] = useState(false);
  const [activeCategory, setActiveCategory] = useState('전체');
  const [hoveredReviewer, setHoveredReviewer] = useState(null);

  // 인기 리뷰어 데이터
  const topReviewers = [
    {
      id: 1,
      name: '뷰티민지',
      username: '@beauty_minji',
      avatar: 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=200&h=200&fit=crop&crop=face',
      followers: '12.3만',
      reviews: 234,
      specialty: '스킨케어',
      verified: true,
      bio: '피부과 전문의 출신 뷰티 크리에이터 💫',
      recentReview: '라네즈 워터뱅크 크림 솔직 리뷰',
      gradient: 'linear-gradient(135deg, #ff9a9e 0%, #fecfef 100%)'
    },
    {
      id: 2,
      name: '스킨케어수아',
      username: '@skincare_sua',
      avatar: 'https://images.unsplash.com/photo-1529626455594-4ff0802cfb7e?w=200&h=200&fit=crop&crop=face',
      followers: '8.7만',
      reviews: 189,
      specialty: '민감성 피부',
      verified: true,
      bio: '민감성 피부 전문 리뷰어 🌸',
      recentReview: '무자극 클렌징 폼 TOP 5',
      gradient: 'linear-gradient(135deg, #a18cd1 0%, #fbc2eb 100%)'
    },
    {
      id: 3,
      name: '인플루언서 채희',
      username: '@chaehee_beauty',
      avatar: 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=200&h=200&fit=crop&crop=face',
      followers: '25.1만',
      reviews: 312,
      specialty: '퍼퓸 & 프래그런스',
      verified: true,
      bio: '트렌디한 메이크업 & 뷰티 인플루언서 ✨',
      recentReview: '롬앤 신상 틴트 전색상 비교',
      gradient: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)'
    }
  ];

  // 카테고리 목록
  const categories = ['전체', '스킨케어', '메이크업', '헤어케어', '바디케어', '향수'];

  // 트렌딩 태그
  const trendingTags = [
    { tag: '#글로우피부', count: '2.3만' },
    { tag: '#수분크림추천', count: '1.8만' },
    { tag: '#데일리메이크업', count: '1.5만' },
    { tag: '#민감피부', count: '1.2만' },
    { tag: '#비건뷰티', count: '9.8천' },
  ];

  useEffect(() => {
    const load = async () => {
      try {
        setLoading(true);
        const reviewsRes = await fetchReviews({ page: 1, limit: 8 });
        const texts = reviewsRes.data.map(r => r.text);
        const resp = await axios.post('/ai/summarize', { texts });
        setSummary(resp.data.summary);
      } catch (err) {
        console.error('magazine load failed', err);
      } finally {
        setLoading(false);
      }
    };
    load();
  }, []);

  return (
    <div 
      style={{ 
        padding: '40px 20px', 
        minHeight: '100vh',
        background: 'linear-gradient(180deg, #fff 0%, #fff5f7 50%, #faf5ff 100%)',
        position: 'relative'
      }}
    >
      {/* 헤더 */}
      <div style={{ textAlign: 'center', marginBottom: 50, maxWidth: 800, margin: '0 auto 50px' }}>
        <h1 style={{ 
          fontSize: 42, 
          fontWeight: 900, 
          background: 'linear-gradient(135deg, #ff6b9d 0%, #c44cff 50%, #6366f1 100%)',
          WebkitBackgroundClip: 'text',
          WebkitTextFillColor: 'transparent',
          marginBottom: 16
        }}>
          🔍 탐색
        </h1>
        <p style={{ color: '#666', fontSize: 16, lineHeight: 1.6 }}>
          인기 리뷰어들의 생생한 뷰티 리뷰를 만나보세요
        </p>
      </div>

      {/* 카테고리 탭 */}
      <div style={{ 
        display: 'flex', 
        gap: 12, 
        justifyContent: 'center', 
        marginBottom: 40,
        flexWrap: 'wrap'
      }}>
        {categories.map(cat => (
          <button
            key={cat}
            onClick={() => setActiveCategory(cat)}
            style={{
              padding: '10px 24px',
              borderRadius: 25,
              border: 'none',
              background: activeCategory === cat 
                ? 'linear-gradient(135deg, #ff6b9d, #c44cff)' 
                : 'white',
              color: activeCategory === cat ? 'white' : '#666',
              fontWeight: 600,
              fontSize: 14,
              cursor: 'pointer',
              boxShadow: activeCategory === cat 
                ? '0 4px 15px rgba(255,107,157,0.4)' 
                : '0 2px 8px rgba(0,0,0,0.08)',
              transition: 'all 0.3s ease',
              transform: activeCategory === cat ? 'scale(1.05)' : 'scale(1)'
            }}
          >
            {cat}
          </button>
        ))}
      </div>

      {/* 인기 리뷰어 섹션 */}
      <div style={{ maxWidth: 1200, margin: '0 auto 60px' }}>
        <div style={{ 
          display: 'flex', 
          alignItems: 'center', 
          justifyContent: 'space-between',
          marginBottom: 24 
        }}>
          <h2 style={{ 
            fontSize: 24, 
            fontWeight: 800, 
            color: '#1a1a2e',
            display: 'flex',
            alignItems: 'center',
            gap: 10
          }}>
            <span>⭐</span> 인기 리뷰어
          </h2>
          <button style={{
            background: 'none',
            border: 'none',
            color: '#ff6b9d',
            fontWeight: 600,
            cursor: 'pointer',
            fontSize: 14
          }}>
            전체 보기 →
          </button>
        </div>

        <div style={{ 
          display: 'grid', 
          gridTemplateColumns: 'repeat(auto-fit, minmax(350px, 1fr))', 
          gap: 24 
        }}>
          {topReviewers.map((reviewer, idx) => (
            <div
              key={reviewer.id}
              onMouseEnter={() => setHoveredReviewer(reviewer.id)}
              onMouseLeave={() => setHoveredReviewer(null)}
              style={{
                background: 'white',
                borderRadius: 24,
                padding: 0,
                overflow: 'hidden',
                boxShadow: hoveredReviewer === reviewer.id 
                  ? '0 20px 60px rgba(255,107,157,0.25)' 
                  : '0 8px 30px rgba(0,0,0,0.08)',
                transition: 'all 0.4s cubic-bezier(0.4, 0, 0.2, 1)',
                transform: hoveredReviewer === reviewer.id ? 'translateY(-8px) scale(1.02)' : 'translateY(0) scale(1)',
                cursor: 'pointer'
              }}
            >
              {/* 그라데이션 헤더 */}
              <div style={{
                background: reviewer.gradient,
                padding: '30px 24px 60px',
                position: 'relative'
              }}>
                {/* 팔로워 뱃지 */}
                <div style={{
                  position: 'absolute',
                  top: 16,
                  right: 16,
                  background: 'rgba(255,255,255,0.25)',
                  backdropFilter: 'blur(10px)',
                  borderRadius: 20,
                  padding: '6px 14px',
                  fontSize: 12,
                  fontWeight: 700,
                  color: 'white'
                }}>
                  👥 {reviewer.followers} 팔로워
                </div>
              </div>

              {/* 프로필 영역 */}
              <div style={{ padding: '0 24px 24px', marginTop: -50 }}>
                {/* 프로필 이미지 */}
                <div style={{
                  width: 100,
                  height: 100,
                  borderRadius: '50%',
                  border: '4px solid white',
                  overflow: 'hidden',
                  boxShadow: '0 8px 24px rgba(0,0,0,0.15)',
                  marginBottom: 16,
                  position: 'relative'
                }}>
                  <img 
                    src={reviewer.avatar} 
                    alt={reviewer.name}
                    style={{
                      width: '100%',
                      height: '100%',
                      objectFit: 'cover'
                    }}
                  />
                  {reviewer.verified && (
                    <div style={{
                      position: 'absolute',
                      bottom: 4,
                      right: 4,
                      width: 24,
                      height: 24,
                      borderRadius: '50%',
                      background: 'linear-gradient(135deg, #4facfe, #00f2fe)',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      fontSize: 12,
                      color: 'white',
                      border: '2px solid white'
                    }}>✓</div>
                  )}
                </div>

                {/* 이름 & 유저네임 */}
                <div style={{ marginBottom: 12 }}>
                  <h3 style={{ 
                    fontSize: 20, 
                    fontWeight: 800, 
                    color: '#1a1a2e',
                    marginBottom: 4,
                    display: 'flex',
                    alignItems: 'center',
                    gap: 8
                  }}>
                    {reviewer.name}
                  </h3>
                  <p style={{ color: '#888', fontSize: 14 }}>{reviewer.username}</p>
                </div>

                {/* 바이오 */}
                <p style={{ 
                  color: '#555', 
                  fontSize: 14, 
                  lineHeight: 1.5,
                  marginBottom: 16 
                }}>
                  {reviewer.bio}
                </p>

                {/* 통계 */}
                <div style={{ 
                  display: 'flex', 
                  gap: 20, 
                  marginBottom: 16,
                  padding: '12px 0',
                  borderTop: '1px solid #f0f0f0',
                  borderBottom: '1px solid #f0f0f0'
                }}>
                  <div style={{ textAlign: 'center' }}>
                    <div style={{ fontSize: 18, fontWeight: 800, color: '#ff6b9d' }}>{reviewer.reviews}</div>
                    <div style={{ fontSize: 12, color: '#888' }}>리뷰</div>
                  </div>
                  <div style={{ textAlign: 'center' }}>
                    <div style={{ fontSize: 18, fontWeight: 800, color: '#c44cff' }}>{reviewer.followers}</div>
                    <div style={{ fontSize: 12, color: '#888' }}>팔로워</div>
                  </div>
                  <div style={{ flex: 1, textAlign: 'right' }}>
                    <span style={{
                      background: 'linear-gradient(135deg, #ff6b9d20, #c44cff20)',
                      color: '#c44cff',
                      padding: '6px 14px',
                      borderRadius: 20,
                      fontSize: 12,
                      fontWeight: 700
                    }}>
                      #{reviewer.specialty}
                    </span>
                  </div>
                </div>

                {/* 최근 리뷰 */}
                <div style={{
                  background: '#f8f9fa',
                  borderRadius: 12,
                  padding: 14,
                  marginBottom: 16
                }}>
                  <div style={{ fontSize: 11, color: '#888', marginBottom: 6 }}>📝 최근 리뷰</div>
                  <div style={{ fontSize: 14, fontWeight: 600, color: '#333' }}>{reviewer.recentReview}</div>
                </div>

                {/* 팔로우 버튼 */}
                <button style={{
                  width: '100%',
                  padding: '14px',
                  borderRadius: 14,
                  border: 'none',
                  background: 'linear-gradient(135deg, #ff6b9d 0%, #c44cff 100%)',
                  color: 'white',
                  fontWeight: 700,
                  fontSize: 15,
                  cursor: 'pointer',
                  transition: 'all 0.3s ease',
                  boxShadow: '0 4px 15px rgba(255,107,157,0.3)'
                }}
                onMouseOver={e => {
                  e.currentTarget.style.transform = 'scale(1.02)';
                  e.currentTarget.style.boxShadow = '0 6px 20px rgba(255,107,157,0.4)';
                }}
                onMouseOut={e => {
                  e.currentTarget.style.transform = 'scale(1)';
                  e.currentTarget.style.boxShadow = '0 4px 15px rgba(255,107,157,0.3)';
                }}
                >
                  + 팔로우
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* 트렌딩 태그 */}
      <div style={{ maxWidth: 1200, margin: '0 auto 60px' }}>
        <h2 style={{ 
          fontSize: 24, 
          fontWeight: 800, 
          color: '#1a1a2e',
          marginBottom: 24,
          display: 'flex',
          alignItems: 'center',
          gap: 10
        }}>
          <span>🔥</span> 트렌딩 태그
        </h2>
        <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap' }}>
          {trendingTags.map((item, idx) => (
            <div
              key={idx}
              style={{
                background: 'white',
                borderRadius: 16,
                padding: '14px 20px',
                display: 'flex',
                alignItems: 'center',
                gap: 10,
                boxShadow: '0 4px 15px rgba(0,0,0,0.06)',
                cursor: 'pointer',
                transition: 'all 0.3s ease'
              }}
              onMouseOver={e => {
                e.currentTarget.style.transform = 'translateY(-3px)';
                e.currentTarget.style.boxShadow = '0 8px 25px rgba(255,107,157,0.15)';
              }}
              onMouseOut={e => {
                e.currentTarget.style.transform = 'translateY(0)';
                e.currentTarget.style.boxShadow = '0 4px 15px rgba(0,0,0,0.06)';
              }}
            >
              <span style={{ 
                fontWeight: 700, 
                fontSize: 15,
                background: 'linear-gradient(135deg, #ff6b9d, #c44cff)',
                WebkitBackgroundClip: 'text',
                WebkitTextFillColor: 'transparent'
              }}>
                {item.tag}
              </span>
              <span style={{ 
                fontSize: 12, 
                color: '#888',
                background: '#f0f0f0',
                padding: '4px 10px',
                borderRadius: 10
              }}>
                {item.count}
              </span>
            </div>
          ))}
        </div>
      </div>

      {/* AI 리뷰 요약 섹션 */}
      <div style={{ maxWidth: 1200, margin: '0 auto' }}>
        <h2 style={{ 
          fontSize: 24, 
          fontWeight: 800, 
          color: '#1a1a2e',
          marginBottom: 24,
          display: 'flex',
          alignItems: 'center',
          gap: 10
        }}>
          <span>🤖</span> AI 리뷰 매거진
        </h2>
        <p style={{ color: '#666', marginBottom: 20 }}>AI가 여러 리뷰를 분석해 트렌드와 핵심을 정리해드립니다.</p>

        {loading && (
          <div style={{ 
            padding: 40, 
            textAlign: 'center', 
            background: 'white', 
            borderRadius: 16,
            boxShadow: '0 4px 15px rgba(0,0,0,0.06)'
          }}>
            <div style={{ fontSize: 40, marginBottom: 16 }}>✨</div>
            <p style={{ color: '#888' }}>AI가 리뷰를 분석 중입니다...</p>
          </div>
        )}

        {summary && (
          <div style={{ 
            padding: 24, 
            background: 'white', 
            borderRadius: 20, 
            boxShadow: '0 8px 30px rgba(0,0,0,0.08)',
            border: '1px solid rgba(255,107,157,0.1)'
          }}>
            <div dangerouslySetInnerHTML={{ __html: summary.replace(/\n/g, '<br/>') }} />
          </div>
        )}
      </div>

      {/* 스타일 */}
      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(20px); }
          to { opacity: 1; transform: translateY(0); }
        }
      `}</style>
    </div>
  );
}

export default Magazine;
